                           author_id, author_label, created_at, event_starts_at, event_place) VALUES
('74000000-0000-4000-8000-000000000001', 'news', 'Клуб дебатов: открытая тренировка', 'Разберём формат британских парламентских дебатов и проведём две пробные игры. Опыт не нужен, достаточно прийти за десять минут до начала.', false, false, 'all', NULL, '40000000-0000-4000-8000-000000000003', 'Администрация', '2026-11-09 09:00:00+03:00', '2026-11-13 18:30:00+03:00', 'Корпус Б, аудитория 1051'),
('74000000-0000-4000-8000-000000000002', 'news', 'ФМО: встреча с выпускниками о стажировках', 'Выпускники факультета расскажут, как искали первую стажировку и что спрашивали на собеседованиях. Вопросы можно задать после встречи.', false, false, 'faculty', '10000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'Деканат ФМО', '2026-11-12 10:00:00+03:00', '2026-11-20 17:00:00+03:00', 'Новый корпус, аудитория 212'),
('74000000-0000-4000-8000-000000000003', 'news', 'Открытая лекция «Как читать международный договор»', 'На примерах учебных договоров разберём структуру текста, оговорки и порядок вступления в силу. Лекция подойдёт студентам любого курса.', false, false, 'all', NULL, '40000000-0000-4000-8000-000000000003', 'Администрация', '2026-11-14 10:00:00+03:00', '2026-11-26 16:00:00+03:00', 'Корпус Г, аудитория 2115'),
('74000000-0000-4000-8000-000000000004', 'news', 'Мастер-класс: резюме для стажировки', 'Покажем, как описать учёбу, проекты и языки на одной странице. Возьмите с собой черновик резюме, если он уже есть.', false, false, 'all', NULL, '40000000-0000-4000-8000-000000000003', 'Администрация', '2026-11-16 09:00:00+03:00', '2026-12-03 15:00:00+03:00', 'Корпус Г, аудитория 3124');

